export const getListLogsUrl = (params?: ListLogsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/logs?${stringifiedParams}` : `/api/logs`
}

/**
 * @summary List recent structured processing logs
 */
export const listLogs = async (params?: ListLogsParams, options?: Parameters<typeof customFetch>[1]): Promise<LogEntry[]> => {

  return customFetch<LogEntry[]>(getListLogsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





